class Pin {
  #kode;
  #percobaan = 0;
  constructor(kode) {
    this.#kode = kode;
  }
  cek(tebakan) {
    if (this.#percobaan >= 3) return "Terblokir";
    if (tebakan === this.#kode) return "Benar";
    this.#percobaan++;
    return "Salah";
  }
}
const pin = new Pin("1234");
console.log(pin.cek("0000"));
console.log(pin.cek("1111"));
console.log(pin.cek("2222"));
console.log(pin.cek("1234"));

