cards.solution:
class Akun {
  #password;
  constructor(username, password) {
    this.username = username;
    this.#password = password;
  }
  gantiPassword(lama, baru) {
    if (lama !== this.#password || baru.length < 8) {
      return "Gagal";
    }
    this.#password = baru;
    return "Berhasil";
  }
}
const a = new Akun("rina", "rahasia123");
console.log(a.gantiPassword("salah", "passwordbaru"));
console.log(a.gantiPassword("rahasia123", "pendek"));
console.log(a.gantiPassword("rahasia123", "passwordbaru"));
console.log(a.gantiPassword("passwordbaru", "lebihpanjang1"));
console.log(a.password);
